"const duoPlayer={x:84,y:0,r:18,speed:255,life:100,maxLife:100,moving:false,walk:0,aim:0,shotFlash:0,connected:false,down:false,fireRate:.28,xpMult:1,regen:0,armorReduction:0,damage:2,bloodChance:0,bloodHeal:0,flashDamage:0,arcLv:0,pierceLv:0,phoenixReady:false,phoenixConsumed:false,invUntil:0,lastDamageAt:0,downKiller:null};const duoInput={dx:0,dy:0};const duoSkillLv={speed:0,medic:0,rapid:0,xp:0,flash:0,regen:0,blood:0,arc:0,phoenix:0,armor:0,pierce:0};let duoConn=null,duoShotTimer=.05,duoEntitySeq=1,duoShotCounter=0,duoArcNextAt=0,duoLevel=1,duoXp=0,duoXpNeed=60,duoKillCount=0,duoPendingSkill=null,reviveP1Ms=0,reviveP2Ms=0,lastCoopKiller=null;const REVIVE_RADIUS=68,REVIVE_MS=3000;",
