old_target="function duoEnemyTarget(e){if(!duoPlayer.connected||duoPlayer.down)return player;const d1=(e.x-player.x)*(e.x-player.x)+(e.y-player.y)*(e.y-player.y),d2=(e.x-duoPlayer.x)*(e.x-duoPlayer.x)+(e.y-duoPlayer.y)*(e.y-duoPlayer.y);return d2<d1?duoPlayer:player}"
helpers=r"""
function duoSkillCap(id){return id==='phoenix'?1:id==='armor'?4:5}
function queueDuoSkill(){if(duoPendingSkill)return;const pool=skills.filter(s=>{const cur=duoSkillLv[s.id]||0;if(s.id==='phoenix')return !duoPlayer.phoenixConsumed&&!duoPlayer.phoenixReady&&cur<1;return cur<duoSkillCap(s.id)});if(!pool.length)return;const available=[...pool],pick=[];while(pick.length<Math.min(3,pool.length)){const s=weightedPick(available);pick.push(s);available.splice(available.indexOf(s),1)}duoPendingSkill=pick.map(s=>{const next=s.id==='phoenix'?1:Math.min(duoSkillCap(s.id),(duoSkillLv[s.id]||0)+1);return{id:s.id,n:s.n,i:s.i,r:s.r,rarity:rarityLabel[s.r],next,desc:s.desc(next)}})}
function gainDuoXP(v){duoXp+=Math.max(0,+v||0)*(duoPlayer.xpMult||1);if(!duoPendingSkill&&duoXp>=duoXpNeed){duoXp-=duoXpNeed;duoLevel++;duoXpNeed=Math.floor(60*Math.pow(duoLevel,1.42));queueDuoSkill()}sendDuoSnapshot()}
function applyDuoSkill(id){id=String(id||'');if(!duoPendingSkill||!duoPendingSkill.some(x=>x.id===id))return false;const lv=id==='phoenix'?1:Math.min(duoSkillCap(id),(duoSkillLv[id]||0)+1);duoSkillLv[id]=lv;if(id==='speed')duoPlayer.speed=255*(1+lv*.10);if(id==='medic'){duoPlayer.maxLife+=10;duoPlayer.life=Math.min(duoPlayer.maxLife,duoPlayer.life+25)}if(id==='rapid')duoPlayer.fireRate=.28*(1-[0,.10,.20,.30,.45,.60][lv]);if(id==='regen')duoPlayer.regen=[0,.4,.6,.8,1,1.2][lv];if(id==='armor')duoPlayer.armorReduction=[0,.05,.09,.13,.18][lv];if(id==='xp')duoPlayer.xpMult=1+lv*.20;if(id==='blood'){duoPlayer.bloodChance=[0,.10,.12,.15,.18,.20][lv];duoPlayer.bloodHeal=[0,.5,.75,1,1.5,2][lv]}if(id==='flash')duoPlayer.flashDamage=[0,8,10,12,15,18][lv];if(id==='arc'){duoPlayer.arcLv=lv;duoArcNextAt=performance.now()+500}if(id==='pierce')duoPlayer.pierceLv=lv;if(id==='phoenix'){duoPlayer.phoenixReady=true;duoPlayer.phoenixConsumed=false}duoPendingSkill=null;gainDuoXP(0);return true}
function tryDuoPhoenix(){if(!duoPlayer.phoenixReady||duoPlayer.phoenixConsumed)return false;duoPlayer.phoenixReady=false;duoPlayer.phoenixConsumed=true;duoSkillLv.phoenix=0;duoPlayer.down=false;duoPlayer.life=Math.max(1,duoPlayer.maxLife*.8);duoPlayer.invUntil=performance.now()+5000;toast('🔥 P2 FÊNIX · 80% HP · ESCUDO 5s');return true}
function reviveCoop(which){if(which==='p1'){player.down=false;player.downKiller=null;player.life=Math.max(1,player.maxLife*.55);player.inv=1.2;reviveP1Ms=0;toast('🤝 P1 REVIVIDO · 55% HP')}else{duoPlayer.down=false;duoPlayer.downKiller=null;duoPlayer.life=Math.max(1,duoPlayer.maxLife*.55);duoPlayer.invUntil=performance.now()+1200;reviveP2Ms=0;toast('🤝 P2 REVIVIDO · 55% HP')}sendDuoSnapshot()}
function knockDownPlayer(which,killer){lastCoopKiller=killer||lastCoopKiller;if(which==='p1'){if(!duoPlayer.connected){beginDeath(killer);return}player.down=true;player.downKiller=killer||null;player.life=0;player.moving=false;pointer=null;reviveP1Ms=0;toast('P1 CAIU · P2 PRECISA FICAR 3s NO CAMPO')}else{duoPlayer.down=true;duoPlayer.downKiller=killer||null;duoPlayer.life=0;duoPlayer.moving=false;duoInput.dx=duoInput.dy=0;reviveP2Ms=0;toast('P2 CAIU · P1 PRECISA FICAR 3s NO CAMPO')}if(player.down&&(!duoPlayer.connected||duoPlayer.down)&&!deathState)beginDeath(killer||lastCoopKiller)}
function updateCoopRevive(dt){if(!duoPlayer.connected){reviveP1Ms=reviveP2Ms=0;if(player.down&&!deathState)beginDeath(player.downKiller||lastCoopKiller);return}if(player.down&&duoPlayer.down){if(!deathState)beginDeath(lastCoopKiller||player.downKiller||duoPlayer.downKiller);return}const d=Math.hypot(player.x-duoPlayer.x,player.y-duoPlayer.y);if(player.down&&!duoPlayer.down){reviveP1Ms=d<=REVIVE_RADIUS?Math.min(REVIVE_MS,reviveP1Ms+dt*1000):0;if(reviveP1Ms>=REVIVE_MS)reviveCoop('p1')}else reviveP1Ms=0;if(duoPlayer.down&&!player.down){reviveP2Ms=d<=REVIVE_RADIUS?Math.min(REVIVE_MS,reviveP2Ms+dt*1000):0;if(reviveP2Ms>=REVIVE_MS)reviveCoop('p2')}else reviveP2Ms=0}
function duoEnemyTarget(e){if(player.down&&duoPlayer.connected&&!duoPlayer.down)return duoPlayer;if(!duoPlayer.connected||duoPlayer.down)return player;if(player.down)return duoPlayer;const d1=(e.x-player.x)*(e.x-player.x)+(e.y-player.y)*(e.y-player.y),d2=(e.x-duoPlayer.x)*(e.x-duoPlayer.x)+(e.y-duoPlayer.y)*(e.y-duoPlayer.y);return d2<d1?duoPlayer:player}
""".strip()
