# P2 shooting + supported skill effects.
old_shoot="function duoShoot(){if(!duoPlayer.connected||duoPlayer.down)return;const t=duoNearestTarget();if(!t)return;duoPlayer.aim=Math.atan2(t.y-duoPlayer.y,t.x-duoPlayer.x);duoPlayer.shotFlash=.10;const dir=playerFacing(duoPlayer.aim),m=muzzleLocal(dir);bullets.push({x:duoPlayer.x+m.x,y:duoPlayer.y+m.y,vx:Math.cos(duoPlayer.aim)*610,vy:Math.sin(duoPlayer.aim)*610,r:4,dead:false,ammo:1,born:performance.now(),pierceLeft:0,hits:[],owner:'p2',damage:2})}"
new_shoot="function duoShoot(){if(!duoPlayer.connected||duoPlayer.down)return;const t=duoNearestTarget();if(!t)return;duoPlayer.aim=Math.atan2(t.y-duoPlayer.y,t.x-duoPlayer.x);duoPlayer.shotFlash=.10;duoShotCounter++;const dir=playerFacing(duoPlayer.aim),m=muzzleLocal(dir),pl=duoPlayer.pierceLv||0,every=[0,12,11,10,9,8][pl]||999,pass=[0,2,3,4,5,7][pl]||0,pierceLeft=pl&&duoShotCounter%every===0?pass:0,flash=duoSkillLv.flash&&duoShotCounter%5===0,damage=(duoPlayer.damage||2)+(flash?(duoPlayer.flashDamage||0):0);bullets.push({x:duoPlayer.x+m.x,y:duoPlayer.y+m.y,vx:Math.cos(duoPlayer.aim)*610,vy:Math.sin(duoPlayer.aim)*610,r:4,dead:false,ammo:1,born:performance.now(),pierceLeft,hits:[],owner:'p2',damage})}"
g=must(g,old_shoot,new_shoot,'duo shoot')

old_update_duo="function updateDuo(dt){if(!duoPlayer.connected)return;duoPlayer.shotFlash=Math.max(0,duoPlayer.shotFlash-dt);if(duoPlayer.down){if(performance.now()>=(duoPlayer.downUntil||0)){duoPlayer.down=false;duoPlayer.life=Math.max(1,duoPlayer.maxLife*.6)}return}let dx=Number(duoInput.dx)||0,dy=Number(duoInput.dy)||0,n=Math.hypot(dx,dy);duoPlayer.moving=n>.05;if(duoPlayer.moving){dx/=n;dy/=n;duoPlayer.x+=dx*duoPlayer.speed*dt;duoPlayer.y+=dy*duoPlayer.speed*dt;duoPlayer.walk+=dt*9}const t=duoNearestTarget();if(t)duoPlayer.aim=Math.atan2(t.y-duoPlayer.y,t.x-duoPlayer.x);duoShotTimer-=dt;if(duoShotTimer<=0){duoShoot();duoShotTimer=.28}}"
new_update_duo="function castDuoArc(){const lv=duoPlayer.arcLv||0,now=performance.now();if(!lv||now<duoArcNextAt)return;const first=duoNearestTarget();if(!first)return;const cds=[0,8,7.5,7,6.5,6],maxTargets=[0,2,2,3,3,4],damage=[0,2,3,4,5,6];duoArcNextAt=now+cds[lv]*1000;const hit=[first];while(hit.length<maxTargets[lv]){const last=hit[hit.length-1];let next=null,bd=190;for(const e of enemies){if(e.dead||hit.includes(e))continue;const d=Math.hypot(e.x-last.x,e.y-last.y);if(d<bd){bd=d;next=e}}if(!next)break;hit.push(next)}for(const e of hit){e.hp-=damage[lv];addDamageFx(e,damage[lv],'arc');if(e.hp<=0&&!e.dead){e.dead=true;onKill(e,'p2')}}}function updateDuo(dt){if(!duoPlayer.connected)return;duoPlayer.shotFlash=Math.max(0,duoPlayer.shotFlash-dt);if(duoPlayer.down){duoPlayer.moving=false;return}let dx=Number(duoInput.dx)||0,dy=Number(duoInput.dy)||0,n=Math.hypot(dx,dy);duoPlayer.moving=n>.05;if(duoPlayer.moving){dx/=n;dy/=n;duoPlayer.x+=dx*duoPlayer.speed*dt;duoPlayer.y+=dy*duoPlayer.speed*dt;duoPlayer.walk+=dt*9}const now=performance.now();if(duoPlayer.regen>0&&duoPlayer.life<duoPlayer.maxLife&&(now-(duoPlayer.lastDamageAt||0))>1000)duoPlayer.life=Math.min(duoPlayer.maxLife,duoPlayer.life+duoPlayer.regen*dt);const t=duoNearestTarget();if(t)duoPlayer.aim=Math.atan2(t.y-duoPlayer.y,t.x-duoPlayer.x);castDuoArc();duoShotTimer-=dt;if(duoShotTimer<=0){duoShoot();duoShotTimer=duoPlayer.fireRate||.28}}"
g=must(g,old_update_duo,new_update_duo,'duo update / no auto revive')

# Independent kill XP attribution.
old_onkill="function onKill(e){killCount++;score+=e.max>=100?500:e.tier===2?35:e.tier===1?20:10;gainXP(e.xp);if(skillLv.blood&&killCount%10===0){if(Math.random()<player.bloodChance){player.maxLife+=1;player.life+=1;toast('🩸 SANGUINÁRIO: +1 HP MÁXIMO')}else{player.life=Math.min(player.maxLife,player.life+player.bloodHeal);toast('🩸 SANGUINÁRIO: +'+String(player.bloodHeal).replace('.',',')+' HP')}}}"
new_onkill="function onKill(e,owner='p1'){killCount++;score+=e.max>=100?500:e.tier===2?35:e.tier===1?20:10;if(owner==='p2'&&duoPlayer.connected){duoKillCount++;gainDuoXP(e.xp);if(duoSkillLv.blood&&duoKillCount%10===0){if(Math.random()<duoPlayer.bloodChance){duoPlayer.maxLife+=1;duoPlayer.life+=1}else duoPlayer.life=Math.min(duoPlayer.maxLife,duoPlayer.life+duoPlayer.bloodHeal)}}else{gainXP(e.xp);if(skillLv.blood&&killCount%10===0){if(Math.random()<player.bloodChance){player.maxLife+=1;player.life+=1;toast('🩸 SANGUINÁRIO: +1 HP MÁXIMO')}else{player.life=Math.min(player.maxLife,player.life+player.bloodHeal);toast('🩸 SANGUINÁRIO: +'+String(player.bloodHeal).replace('.',',')+' HP')}}}}"
