new_snapshot="""function duoSnapshot(){const rr=820*820,near=enemies.filter(e=>{if(e.dead)return false;const dx=e.x-duoPlayer.x,dy=e.y-duoPlayer.y;return dx*dx+dy*dy<rr}).slice(0,56).map(e=>({id:e.duoNetId||(e.duoNetId=duoEntitySeq++),x:e.x,y:e.y,r:e.r,type:e.type,tier:e.tier,hp:e.hp,max:e.max,facing:e.facing,t:e.t,speedMul:e.speedMul||1})),bs=bullets.filter(b=>{if(b.flash||b.dead)return false;const dx=b.x-duoPlayer.x,dy=b.y-duoPlayer.y;return dx*dx+dy*dy<rr}).slice(0,28).map(b=>({x:b.x,y:b.y,owner:b.owner||'p1'})),alive=enemies.reduce((n,e)=>n+(!e.dead?1:0),0);return{type:'duo-snapshot',version:VERSION,map:'snow-frost-puzzle',seed:'ICE-BMFSXT',level,xp:Math.floor(xp),xpNeed,mobsTotal:alive,kills:killCount,gameOver:!!deathState,p1:{x:player.x,y:player.y,life:player.life,maxLife:player.maxLife,aim:player.aim,down:!!player.down,moving:player.moving,walk:player.walk,shotFlash:player.shotFlash},p2:{x:duoPlayer.x,y:duoPlayer.y,life:duoPlayer.life,maxLife:duoPlayer.maxLife,aim:duoPlayer.aim,down:duoPlayer.down,moving:duoPlayer.moving,walk:duoPlayer.walk,shotFlash:duoPlayer.shotFlash,speed:duoPlayer.speed},duo:{level:duoLevel,xp:Math.floor(duoXp),xpNeed:duoXpNeed,skills:{...duoSkillLv},choices:duoPendingSkill},revive:{radius:REVIVE_RADIUS,ms:REVIVE_MS,p1:reviveP1Ms,p2:reviveP2Ms},enemies:near,bullets:bs,ts:Date.now()}}\n"""
g=g[:start]+new_snapshot+g[end:]
